package com.yuegang.zhihui.wallet.api;import com.yuegang.zhihui.common.core.*;import com.yuegang.zhihui.common.web.*;import com.yuegang.zhihui.wallet.application.*;import com.yuegang.zhihui.wallet.security.*;import jakarta.servlet.http.*;import jakarta.validation.Valid;import org.springframework.web.bind.annotation.*;@RestController @RequestMapping("/api/v1/wallet")public final class WalletController{private final WalletService service;private final WalletUserResolver users;public WalletController(WalletService s,WalletUserResolver u){service=s;users=u;}@GetMapping ApiResponse<WalletView>get(HttpServletRequest r){return ok(service.get(users.resolve(r)),r);}@PostMapping("/recharges")ApiResponse<WalletTransactionView>recharge(@Valid @RequestBody WalletCommand c,HttpServletRequest r){return ok(service.recharge(users.resolve(r),c),r);}@PostMapping("/payments")ApiResponse<WalletTransactionView>pay(@Valid @RequestBody WalletCommand c,HttpServletRequest r){return ok(service.pay(users.resolve(r),c),r);}@PostMapping("/refunds")ApiResponse<WalletTransactionView>refund(@Valid @RequestBody WalletCommand c,HttpServletRequest r){return ok(service.refund(users.resolve(r),c),r);}private static<T>ApiResponse<T>ok(T d,HttpServletRequest r){return ApiResponse.success(d,TraceIdResolver.resolve(r));}}
